xql_query:
// ============================================================
// Rule: O365_Copilot BOT has been created
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with O365_Copilot BOT has been created.
// Severity: SEV_020_LOW
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1204 - User Execution

config case_sensitive = false
| dataset = saas_audit_logs
| filter operation_name_orig = "BotCreate"

// User do evento (UserKey)
| alter UserID = json_extract_scalar(to_json_string(raw_log), "$.UserKey")
| filter UserID != null

// Extrai o JsonPropertiesCollection (JSON em string) e pega o bot.id
| alter jprops = json_extract_scalar(to_json_string(raw_log), "$.JsonPropertiesCollection")
| alter BotID  = json_extract_scalar(jprops, "$['powerplatform.analytics.resource.bot.id']")

// join + diagnóstico
| join conflict_strategy = both type = inner (
      dataset = msft_o365_users_raw
      | fields id, mail, surname, identities, displayName, department, jobTitle
  ) as o365
  o365.id = UserID

| fields UserID, displayName, mail, department, jobTitle, BotID
